/* message / newest */
static const uint8_t vector_message_newest[2u] = {
	0x0A, 0x80,
};

static void test_message_newest(void **state)
{
	uint8_t     buf[2u];
	situ_msg_t  msg;
	situ_view_t view;

	(void)state;
	memcpy(buf, vector_message_newest, sizeof(buf));
	situ_msg_init(&msg, buf, 2u);
	situ_check_eq(fzn_messages_local_message_view(&msg, 0, 2u, &view), SITU_OK);
	situ_check_eq(fzn_messages_local_message_validate(view), SITU_OK);

	/* Every value written back through its own setter must reproduce the
	 * bytes it came from. This is what catches a layout change. */
	fzn_messages_local_message_cmd_set(view, fzn_messages_local_message_cmd_get(view));
	fzn_messages_local_message_op_set(&msg, view, fzn_messages_local_message_op_get(view));
	situ_check_bytes(buf, vector_message_newest, sizeof(buf));
}

